package com.android.tools.lint.checks

import com.android.tools.lint.client.api.UElementHandler
import com.android.tools.lint.detector.api.*
import org.jetbrains.uast.*

class AccessibilityForceFocusDetector : Detector(), SourceCodeScanner {

    override fun getApplicableUastTypes() = listOf(UCallExpression::class.java)

    override fun createUastHandler(context: JavaContext) = object : UElementHandler() {
        override fun visitCallExpression(node: UCallExpression) {
            val methodName = node.methodName ?: return
            if (methodName !in APPLICABLE_METHODS) return
            val arg = node.valueArguments.firstOrNull() ?: return
            val value = ConstantEvaluator.evaluate(context, arg)
            if (value == AccessibilityEvent.TYPE_VIEW_FOCUSED || value == AccessibilityNodeInfo.ACTION_ACCESSIBILITY_FOCUS) {
                report(context, node)
            } else if (arg is UReferenceExpression) {
                val name = arg.resolvedName ?: (arg as? USimpleNameReferenceExpression)?.identifier
                if (name == "TYPE_VIEW_FOCUSED" || name == "ACTION_ACCESSIBILITY_FOCUS") {
                    report(context, node)
                }
            }
        }
    }

    private fun report(context: JavaContext, node: UCallExpression) {
        context.report(
            ISSUE,
            node,
            context.getLocation(node),
            "Avoid forcing accessibility focus"
        )
    }

    companion object {
        private val APPLICABLE_METHODS = listOf(
            "sendAccessibilityEvent",
            "sendAccessibilityEventUnchecked",
            "performAccessibilityAction",
            "performAction"
        )

        val ISSUE = Issue.create(
            id = "AccessibilityFocus",
            briefDescription = "Forcing accessibility focus",
            explanation = """
                Forcing accessibility focus interferes with screen readers and gives an
                inconsistent user experience, especially across apps.
            """.trimIndent(),
            category = Category.ACCESSIBILITY,
            priority = 3,
            severity = Severity.WARNING,
            implementation = Implementation(
                AccessibilityForceFocusDetector::class.java,
                Scope.JAVA_FILE_SCOPE
            )
        )
    }
}
```

